Object.assign(BESEDILA_OS.sl, {"kanaliNaslov": "Kanali", "kanalAplikacije": "Aplikacije", "kanalLastniApi": "Lastni API", "kanalLastniApiOpis": "Če imaš žeton svoje aplikacije, ga vpiši tukaj – sporočila pridejo v skupni nabiralnik.", "kanalApiIme": "Ime kanala (neobvezno)", "navMatrix": "Matrix (Element, Beeper, lastni Synapse): v aplikaciji Element odpri Nastavitve › Pomoč in o programu › Napredno › Dostopni žeton in ga prepiši sem. Naslov strežnika je tisti, na katerem imaš račun (npr. https://matrix.org).", "navTelegramBot": "Telegram Bot: v Telegramu piši @BotFather, pošlji /newbot in sledi navodilom – dobiš žeton oblike 123456:ABC… Bot prejema sporočila ljudi, ki mu pišejo; tvojega zasebnega računa Telegram tako ne odpira.", "kanalKjeImas": "Kje imaš e-pošto? Izberi ponudnika – strežnike pozna Safeer, ti vpišeš le naslov in geslo.", "kanalDrugPonudnik": "‹ Drug ponudnik", "kanalDrugPonudnikIme": "Drug ponudnik", "kanalDrugPonudnikOpis": "Vpiši naslov – strežnika predlagava sama.", "kanalNiNaVoljo": "ni na voljo", "kanalNapredno": "Strežniki (napredno)", "kanalKajNarediti": "Kaj moraš narediti", "kanalNaslovPri": "Tvoj naslov pri {ime}", "kanalGesloAplikacije16": "Geslo za aplikacije (16 znakov)", "kanalNavadnoGeslo": "Običajno geslo", "kanalAplikacijeOpis": "Ti ponudniki delujejo le prek svoje aplikacije. Odpre se uradna spletna različica v Safeer OS ali uradna stran za prenos; Safeer ničesar ne prenaša sam.", "kanalAppPosta": "E-pošta", "kanalAppKlepet": "Klepet", "kanalAppSplet": "Odpri v Safeer OS", "kanalAppPrenos": "Prenesi za računalnik", "navGmail": "1. Odpri myaccount.google.com › Varnost in vklopi »Preverjanje v 2 korakih«.\n2. Tam poišči »Gesla za aplikacije«, ustvari novo (ime npr. Safeer) in prepiši 16-mestno geslo.\n3. Sem vpiši svoj Gmail naslov in TO geslo (ne glavnega).\nIMAP je pri Gmailu vklopljen samodejno.", "navYahoo": "1. Odpri login.yahoo.com › Varnost računa › »Ustvari geslo za aplikacijo«.\n2. Prepiši ustvarjeno geslo in ga vpiši sem namesto glavnega.\nUporabniško ime je tvoj celoten Yahoo naslov.", "navIcloud": "1. Odpri account.apple.com › Prijava in varnost › »Gesla za aplikacije« (potrebno je dvostopenjsko preverjanje).\n2. Ustvari geslo za Safeer in ga vpiši sem namesto gesla Apple računa.\nNaslov je tvoj celoten iCloud naslov.", "navGmx": "1. V spletni pošti odpri Nastavitve › POP3/IMAP in vklopi IMAP.\n2. Sem vpiši naslov in svoje običajno geslo.", "navZoho": "1. V Zoho Mail odpri Nastavitve › Poštni računi › »IMAP Access« in ga vklopi.\n2. Če imaš vklopljeno dvostopenjsko preverjanje, v Zoho računu ustvari »App password« in vpiši tega.", "navFastmail": "1. V Fastmailu odpri Nastavitve › Zasebnost in varnost › Integracije › »New app password« (za pošto).\n2. Vpiši naslov in to geslo za aplikacije.", "navArnes": "Vpiši svoj naslov in geslo Arnes. Če prijava ne uspe, Safeer sam poskusi še z uporabniškim imenom brez »@arnes.si«.", "navNavadno": "Vpiši svoj naslov in običajno geslo za pošto. Strežnike in vrata pozna Safeer sam. Če prijava ne uspe, Safeer sam poskusi še z uporabniškim imenom brez domene.", "navOauth": "Microsoft za osebne račune ne dovoli več prijave z geslom (zahteva prijavo OAuth, ki je Safeer še nima). Do takrat uporabi Outlook pod zavihkom »Aplikacije«.", "navDrug": "Vpiši naslov – Safeer predlaga strežnika imap.domena in smtp.domena. Če pri ponudniku piše drugače, ju popravi pod »Strežniki (napredno)«.", "kanalAppVec": "Več kanalov v eni aplikaciji", "kanalStranGesla": "Odpri stran za geslo za aplikacije ({ime})", "kanalCipGeslo": "geslo za aplikacije"});
Object.assign(BESEDILA_OS.en, {"kanaliNaslov": "Channels", "kanalAplikacije": "Apps", "kanalLastniApi": "Own API", "kanalLastniApiOpis": "If you have a token for your own app, enter it here – messages land in the shared inbox.", "kanalApiIme": "Channel name (optional)", "navMatrix": "Matrix (Element, Beeper, own Synapse): in Element open Settings › Help & About › Advanced › Access Token and paste it here. The server address is the one your account lives on (e.g. https://matrix.org).", "navTelegramBot": "Telegram Bot: in Telegram message @BotFather, send /newbot and follow the steps – you get a token like 123456:ABC… The bot receives messages from people who write to it; Telegram does not expose your private account this way.", "kanalKjeImas": "Where is your e-mail? Pick the provider – Safeer knows the servers, you only enter the address and password.", "kanalDrugPonudnik": "‹ Other provider", "kanalDrugPonudnikIme": "Other provider", "kanalDrugPonudnikOpis": "Type your address – we suggest the servers.", "kanalNiNaVoljo": "not available", "kanalNapredno": "Servers (advanced)", "kanalKajNarediti": "What you need to do", "kanalNaslovPri": "Your {ime} address", "kanalGesloAplikacije16": "App password (16 characters)", "kanalNavadnoGeslo": "Usual password", "kanalAplikacijeOpis": "These providers only work through their own app. The official web version opens inside Safeer OS, or the official download page; Safeer downloads nothing itself.", "kanalAppPosta": "E-mail", "kanalAppKlepet": "Chat", "kanalAppSplet": "Open in Safeer OS", "kanalAppPrenos": "Download for computer", "navGmail": "1. Open myaccount.google.com › Security and turn on 2-Step Verification.\n2. There, find “App passwords”, create one (name it e.g. Safeer) and copy the 16-character password.\n3. Enter your Gmail address and THAT password here (not your main one).\nIMAP is on by default in Gmail.", "navYahoo": "1. Open login.yahoo.com › Account security › “Generate app password”.\n2. Copy the generated password and enter it here instead of your main one.\nThe username is your full Yahoo address.", "navIcloud": "1. Open account.apple.com › Sign-In and Security › “App-Specific Passwords” (two-factor authentication required).\n2. Create one for Safeer and enter it here instead of your Apple Account password.\nThe address is your full iCloud address.", "navGmx": "1. In webmail open Settings › POP3/IMAP and enable IMAP.\n2. Enter your address and your usual password here.", "navZoho": "1. In Zoho Mail open Settings › Mail Accounts › “IMAP Access” and enable it.\n2. If two-factor authentication is on, create an “App password” in your Zoho account and enter that.", "navFastmail": "1. In Fastmail open Settings › Privacy & Security › Integrations › “New app password” (for mail).\n2. Enter your address and that app password.", "navArnes": "Enter your Arnes address and password. If sign-in fails, Safeer retries with the username without “@arnes.si” by itself.", "navNavadno": "Enter your address and your usual mail password. Safeer knows the servers and ports. If sign-in fails, Safeer retries with the username without the domain by itself.", "navOauth": "Microsoft no longer allows password sign-in for personal accounts (OAuth sign-in is required, which Safeer does not have yet). Until then use Outlook under the “Apps” tab.", "navDrug": "Type your address – Safeer suggests imap.domain and smtp.domain. If your provider lists different servers, fix them under “Servers (advanced)”.", "kanalAppVec": "Many channels in one app", "kanalStranGesla": "Open the app password page ({ime})", "kanalCipGeslo": "app password"});
Object.assign(BESEDILA_OS.de, {"kanalAppVec": "Viele Kanäle in einer App", "kanalStranGesla": "Seite für App-Passwörter öffnen ({ime})", "kanalCipGeslo": "App-Passwort"});
Object.assign(BESEDILA_OS.es, {"kanalAppVec": "Muchos canales en una app", "kanalStranGesla": "Abrir la página de contraseñas de aplicación ({ime})", "kanalCipGeslo": "contraseña de aplicación"});
