Object.assign(BESEDILA_OS.sl, {"navYahoo": "1. Odpri login.yahoo.com › Varnost računa › »Zunanje povezave« › »Ustvari geslo za aplikacijo«.\n2. Vpiši ime (npr. Safeer), izberi »Ustvari geslo« in ga prepiši sem namesto glavnega.\nUporabniško ime je tvoj celoten Yahoo naslov."});
Object.assign(BESEDILA_OS.en, {"navYahoo": "1. Open login.yahoo.com › Account security › “External connections” › “Create app password”.\n2. Type a name (e.g. Safeer), select “Generate password” and enter it here instead of your main one.\nThe username is your full Yahoo address."});
Object.assign(BESEDILA_OS.de, {"kanaliNaslov": "Kanäle", "kanalAplikacije": "Apps", "kanalLastniApi": "Eigene API", "kanalLastniApiOpis": "Wenn du ein Token deiner eigenen App hast, gib es hier ein – die Nachrichten landen im gemeinsamen Posteingang.", "kanalApiIme": "Name des Kanals (optional)", "navMatrix": "Matrix (Element, Beeper, eigener Synapse): Öffne in Element Einstellungen › Hilfe & Info › Erweitert › Zugriffstoken und füge es hier ein. Die Serveradresse ist die deines Kontos (z. B. https://matrix.org).", "navTelegramBot": "Telegram-Bot: Schreibe in Telegram @BotFather, sende /newbot und folge den Schritten – du bekommst ein Token wie 123456:ABC… Der Bot empfängt Nachrichten von Leuten, die ihm schreiben; dein privates Telegram-Konto wird so nicht geöffnet.", "kanalKjeImas": "Wo ist deine E-Mail? Wähle den Anbieter – Safeer kennt die Server, du gibst nur Adresse und Passwort ein.", "kanalDrugPonudnik": "‹ Anderer Anbieter", "kanalDrugPonudnikIme": "Anderer Anbieter", "kanalDrugPonudnikOpis": "Gib deine Adresse ein – wir schlagen die Server vor.", "kanalNiNaVoljo": "nicht verfügbar", "kanalNapredno": "Server (erweitert)", "kanalKajNarediti": "Was du tun musst", "kanalNaslovPri": "Deine {ime}-Adresse", "kanalGesloAplikacije16": "App-Passwort (16 Zeichen)", "kanalNavadnoGeslo": "Übliches Passwort", "kanalAplikacijeOpis": "Diese Anbieter funktionieren nur über ihre eigene App. Die offizielle Webversion öffnet sich in Safeer OS, oder die offizielle Downloadseite; Safeer lädt selbst nichts herunter.", "kanalAppPosta": "E-Mail", "kanalAppKlepet": "Chat", "kanalAppSplet": "In Safeer OS öffnen", "kanalAppPrenos": "Für den Computer herunterladen", "navGmail": "1. Öffne myaccount.google.com › Sicherheit und aktiviere die Bestätigung in zwei Schritten.\n2. Suche dort „App-Passwörter“, erstelle eines (Name z. B. Safeer) und kopiere das 16-stellige Passwort.\n3. Gib hier deine Gmail-Adresse und DIESES Passwort ein (nicht dein Hauptpasswort).\nIMAP ist bei Gmail automatisch aktiv.", "navYahoo": "1. Öffne login.yahoo.com › Kontosicherheit › „Externe Verbindungen“ › „App-Passwort erstellen“.\n2. Gib einen Namen ein (z. B. Safeer), wähle „Passwort generieren“ und gib es hier statt deines Hauptpassworts ein.\nDer Benutzername ist deine vollständige Yahoo-Adresse.", "navIcloud": "1. Öffne account.apple.com › Anmeldung und Sicherheit › „App-spezifische Passwörter“ (Zwei-Faktor-Authentifizierung nötig).\n2. Erstelle eines für Safeer und gib es hier statt des Apple-Account-Passworts ein.\nDie Adresse ist deine vollständige iCloud-Adresse.", "navGmx": "1. Öffne im Webmail Einstellungen › POP3/IMAP und aktiviere IMAP.\n2. Gib hier deine Adresse und dein übliches Passwort ein.", "navZoho": "1. Öffne in Zoho Mail Einstellungen › E-Mail-Konten › „IMAP Access“ und aktiviere es.\n2. Ist die Zwei-Faktor-Authentifizierung aktiv, erstelle im Zoho-Konto ein „App password“ und gib dieses ein.", "navFastmail": "1. Öffne in Fastmail Einstellungen › Datenschutz & Sicherheit › Integrationen › „New app password“ (für Mail).\n2. Gib deine Adresse und dieses App-Passwort ein.", "navArnes": "Gib deine Arnes-Adresse und dein Passwort ein. Klappt die Anmeldung nicht, versucht es Safeer selbst mit dem Benutzernamen ohne „@arnes.si“.", "navNavadno": "Gib deine Adresse und dein übliches Mail-Passwort ein. Server und Ports kennt Safeer selbst. Klappt die Anmeldung nicht, versucht es Safeer selbst mit dem Benutzernamen ohne Domain.", "navOauth": "Microsoft erlaubt bei privaten Konten keine Anmeldung mit Passwort mehr (OAuth nötig, das Safeer noch nicht hat). Nutze bis dahin Outlook unter „Apps“.", "navDrug": "Gib deine Adresse ein – Safeer schlägt imap.domain und smtp.domain vor. Nennt dein Anbieter andere Server, korrigiere sie unter „Server (erweitert)“."});
Object.assign(BESEDILA_OS.es, {"kanaliNaslov": "Canales", "kanalAplikacije": "Apps", "kanalLastniApi": "API propia", "kanalLastniApiOpis": "Si tienes un token de tu propia app, introdúcelo aquí: los mensajes llegan a la bandeja común.", "kanalApiIme": "Nombre del canal (opcional)", "navMatrix": "Matrix (Element, Beeper, Synapse propio): en Element abre Ajustes › Ayuda y acerca de › Avanzado › Token de acceso y pégalo aquí. La dirección del servidor es la de tu cuenta (p. ej. https://matrix.org).", "navTelegramBot": "Bot de Telegram: en Telegram escribe a @BotFather, envía /newbot y sigue los pasos: obtienes un token como 123456:ABC… El bot recibe los mensajes de quien le escribe; tu cuenta privada de Telegram no se abre así.", "kanalKjeImas": "¿Dónde tienes el correo? Elige el proveedor: Safeer conoce los servidores, tú solo introduces la dirección y la contraseña.", "kanalDrugPonudnik": "‹ Otro proveedor", "kanalDrugPonudnikIme": "Otro proveedor", "kanalDrugPonudnikOpis": "Escribe tu dirección: te sugerimos los servidores.", "kanalNiNaVoljo": "no disponible", "kanalNapredno": "Servidores (avanzado)", "kanalKajNarediti": "Qué tienes que hacer", "kanalNaslovPri": "Tu dirección de {ime}", "kanalGesloAplikacije16": "Contraseña de aplicación (16 caracteres)", "kanalNavadnoGeslo": "Contraseña habitual", "kanalAplikacijeOpis": "Estos proveedores solo funcionan con su propia app. Se abre la versión web oficial dentro de Safeer OS o la página oficial de descarga; Safeer no descarga nada por sí mismo.", "kanalAppPosta": "Correo", "kanalAppKlepet": "Chat", "kanalAppSplet": "Abrir en Safeer OS", "kanalAppPrenos": "Descargar para el ordenador", "navGmail": "1. Abre myaccount.google.com › Seguridad y activa la verificación en dos pasos.\n2. Allí busca «Contraseñas de aplicaciones», crea una (p. ej. Safeer) y copia la contraseña de 16 caracteres.\n3. Introduce aquí tu dirección de Gmail y ESA contraseña (no la principal).\nEn Gmail IMAP está activado de forma predeterminada.", "navYahoo": "1. Abre login.yahoo.com › Seguridad de la cuenta › «Conexiones externas» › «Crear contraseña de aplicación».\n2. Escribe un nombre (p. ej. Safeer), elige «Generar contraseña» e introdúcela aquí en lugar de la principal.\nEl usuario es tu dirección de Yahoo completa.", "navIcloud": "1. Abre account.apple.com › Inicio de sesión y seguridad › «Contraseñas específicas de apps» (requiere autenticación de doble factor).\n2. Crea una para Safeer e introdúcela aquí en lugar de la contraseña de la cuenta de Apple.\nLa dirección es tu dirección de iCloud completa.", "navGmx": "1. En el correo web abre Ajustes › POP3/IMAP y activa IMAP.\n2. Introduce aquí tu dirección y tu contraseña habitual.", "navZoho": "1. En Zoho Mail abre Ajustes › Cuentas de correo › «IMAP Access» y actívalo.\n2. Si tienes la autenticación de dos factores, crea una «App password» en tu cuenta de Zoho e introdúcela.", "navFastmail": "1. En Fastmail abre Ajustes › Privacidad y seguridad › Integraciones › «New app password» (para correo).\n2. Introduce tu dirección y esa contraseña de aplicación.", "navArnes": "Introduce tu dirección y contraseña de Arnes. Si el inicio de sesión falla, Safeer lo reintenta solo con el usuario sin «@arnes.si».", "navNavadno": "Introduce tu dirección y tu contraseña de correo habitual. Safeer conoce los servidores y puertos. Si falla, Safeer lo reintenta solo con el usuario sin dominio.", "navOauth": "Microsoft ya no permite iniciar sesión con contraseña en cuentas personales (requiere OAuth, que Safeer aún no tiene). Mientras tanto usa Outlook en la pestaña «Apps».", "navDrug": "Escribe tu dirección: Safeer sugiere imap.dominio y smtp.dominio. Si tu proveedor indica otros servidores, corrígelos en «Servidores (avanzado)»."});
Object.assign(BESEDILA_OS.fr, {"kanaliNaslov": "Canaux", "kanalAplikacije": "Applis", "kanalLastniApi": "API personnelle", "kanalLastniApiOpis": "Si tu as un jeton de ta propre appli, saisis-le ici – les messages arrivent dans la boîte commune.", "kanalApiIme": "Nom du canal (facultatif)", "navMatrix": "Matrix (Element, Beeper, ton propre Synapse) : dans Element, ouvre Paramètres › Aide et à propos › Avancé › Jeton d’accès et colle-le ici. L’adresse du serveur est celle de ton compte (par ex. https://matrix.org).", "navTelegramBot": "Bot Telegram : dans Telegram, écris à @BotFather, envoie /newbot et suis les étapes – tu obtiens un jeton comme 123456:ABC… Le bot reçoit les messages de ceux qui lui écrivent ; ton compte Telegram privé n’est pas ouvert ainsi.", "kanalKjeImas": "Où est ta messagerie ? Choisis le fournisseur – Safeer connaît les serveurs, tu saisis seulement l’adresse et le mot de passe.", "kanalDrugPonudnik": "‹ Autre fournisseur", "kanalDrugPonudnikIme": "Autre fournisseur", "kanalDrugPonudnikOpis": "Saisis ton adresse – nous proposons les serveurs.", "kanalNiNaVoljo": "indisponible", "kanalNapredno": "Serveurs (avancé)", "kanalKajNarediti": "Ce que tu dois faire", "kanalNaslovPri": "Ton adresse {ime}", "kanalGesloAplikacije16": "Mot de passe d’application (16 caractères)", "kanalNavadnoGeslo": "Mot de passe habituel", "kanalAplikacijeOpis": "Ces fournisseurs ne fonctionnent qu’avec leur propre appli. La version web officielle s’ouvre dans Safeer OS, ou la page de téléchargement officielle ; Safeer ne télécharge rien lui-même.", "kanalAppPosta": "E-mail", "kanalAppKlepet": "Discussion", "kanalAppSplet": "Ouvrir dans Safeer OS", "kanalAppPrenos": "Télécharger pour l’ordinateur", "navGmail": "1. Ouvre myaccount.google.com › Sécurité et active la validation en deux étapes.\n2. Cherche « Mots de passe des applications », crée-en un (nom : Safeer) et copie le mot de passe de 16 caractères.\n3. Saisis ici ton adresse Gmail et CE mot de passe (pas le principal).\nIMAP est activé par défaut dans Gmail.", "navYahoo": "1. Ouvre login.yahoo.com › Sécurité du compte › « Connexions externes » › « Créer un mot de passe d’application ».\n2. Saisis un nom (par ex. Safeer), choisis « Générer le mot de passe » et saisis-le ici à la place du principal.\nL’identifiant est ton adresse Yahoo complète.", "navIcloud": "1. Ouvre account.apple.com › Connexion et sécurité › « Mots de passe pour app » (identification à deux facteurs requise).\n2. Crée-en un pour Safeer et saisis-le ici à la place du mot de passe du compte Apple.\nL’adresse est ton adresse iCloud complète.", "navGmx": "1. Dans le webmail, ouvre Paramètres › POP3/IMAP et active IMAP.\n2. Saisis ici ton adresse et ton mot de passe habituel.", "navZoho": "1. Dans Zoho Mail, ouvre Paramètres › Comptes de messagerie › « IMAP Access » et active-le.\n2. Si l’authentification à deux facteurs est active, crée un « App password » dans ton compte Zoho et saisis-le.", "navFastmail": "1. Dans Fastmail, ouvre Paramètres › Confidentialité et sécurité › Intégrations › « New app password » (pour le courrier).\n2. Saisis ton adresse et ce mot de passe d’application.", "navArnes": "Saisis ton adresse et ton mot de passe Arnes. Si la connexion échoue, Safeer réessaie seul avec l’identifiant sans « @arnes.si ».", "navNavadno": "Saisis ton adresse et ton mot de passe de messagerie habituel. Safeer connaît les serveurs et les ports. En cas d’échec, Safeer réessaie seul avec l’identifiant sans le domaine.", "navOauth": "Microsoft n’autorise plus la connexion par mot de passe pour les comptes personnels (OAuth requis, que Safeer n’a pas encore). En attendant, utilise Outlook dans l’onglet « Applis ».", "navDrug": "Saisis ton adresse – Safeer propose imap.domaine et smtp.domaine. Si ton fournisseur indique d’autres serveurs, corrige-les dans « Serveurs (avancé) »."});
Object.assign(BESEDILA_OS.it, {"kanaliNaslov": "Canali", "kanalAplikacije": "App", "kanalLastniApi": "API propria", "kanalLastniApiOpis": "Se hai un token della tua app, inseriscilo qui: i messaggi arrivano nella posta comune.", "kanalApiIme": "Nome del canale (facoltativo)", "navMatrix": "Matrix (Element, Beeper, Synapse proprio): in Element apri Impostazioni › Aiuto e informazioni › Avanzate › Token di accesso e incollalo qui. L’indirizzo del server è quello del tuo account (es. https://matrix.org).", "navTelegramBot": "Bot Telegram: in Telegram scrivi a @BotFather, invia /newbot e segui i passaggi: ottieni un token come 123456:ABC… Il bot riceve i messaggi di chi gli scrive; il tuo account Telegram privato non viene aperto così.", "kanalKjeImas": "Dove hai la posta? Scegli il provider: Safeer conosce i server, tu inserisci solo indirizzo e password.", "kanalDrugPonudnik": "‹ Altro provider", "kanalDrugPonudnikIme": "Altro provider", "kanalDrugPonudnikOpis": "Scrivi il tuo indirizzo: ti suggeriamo i server.", "kanalNiNaVoljo": "non disponibile", "kanalNapredno": "Server (avanzate)", "kanalKajNarediti": "Cosa devi fare", "kanalNaslovPri": "Il tuo indirizzo {ime}", "kanalGesloAplikacije16": "Password per le app (16 caratteri)", "kanalNavadnoGeslo": "Password abituale", "kanalAplikacijeOpis": "Questi provider funzionano solo con la loro app. Si apre la versione web ufficiale in Safeer OS o la pagina ufficiale di download; Safeer non scarica nulla da sé.", "kanalAppPosta": "E-mail", "kanalAppKlepet": "Chat", "kanalAppSplet": "Apri in Safeer OS", "kanalAppPrenos": "Scarica per il computer", "navGmail": "1. Apri myaccount.google.com › Sicurezza e attiva la verifica in due passaggi.\n2. Lì cerca «Password per le app», creane una (nome es. Safeer) e copia la password di 16 caratteri.\n3. Inserisci qui il tuo indirizzo Gmail e QUELLA password (non quella principale).\nIn Gmail IMAP è attivo di default.", "navYahoo": "1. Apri login.yahoo.com › Sicurezza dell’account › «Connessioni esterne» › «Crea password per app».\n2. Scrivi un nome (es. Safeer), scegli «Genera password» e inseriscila qui al posto di quella principale.\nIl nome utente è il tuo indirizzo Yahoo completo.", "navIcloud": "1. Apri account.apple.com › Accesso e sicurezza › «Password specifiche per le app» (serve l’autenticazione a due fattori).\n2. Creane una per Safeer e inseriscila qui al posto della password dell’account Apple.\nL’indirizzo è il tuo indirizzo iCloud completo.", "navGmx": "1. Nella webmail apri Impostazioni › POP3/IMAP e attiva IMAP.\n2. Inserisci qui il tuo indirizzo e la password abituale.", "navZoho": "1. In Zoho Mail apri Impostazioni › Account di posta › «IMAP Access» e attivalo.\n2. Se l’autenticazione a due fattori è attiva, crea una «App password» nel tuo account Zoho e inserisci quella.", "navFastmail": "1. In Fastmail apri Impostazioni › Privacy e sicurezza › Integrazioni › «New app password» (per la posta).\n2. Inserisci il tuo indirizzo e quella password per le app.", "navArnes": "Inserisci indirizzo e password Arnes. Se l’accesso non riesce, Safeer riprova da solo con il nome utente senza «@arnes.si».", "navNavadno": "Inserisci il tuo indirizzo e la password abituale della posta. Safeer conosce server e porte. Se l’accesso non riesce, Safeer riprova da solo con il nome utente senza dominio.", "navOauth": "Microsoft non consente più l’accesso con password per gli account personali (serve OAuth, che Safeer non ha ancora). Nel frattempo usa Outlook nella scheda «App».", "navDrug": "Scrivi il tuo indirizzo: Safeer suggerisce imap.dominio e smtp.dominio. Se il tuo provider indica altri server, correggili in «Server (avanzate)»."});

