Object.assign(BESEDILA_OS.sl, {"filterKlepeti":"Klepeti","isciSporocila":"Išči po imenu, zadevi ali besedilu …","mapaNeprebrano":"Neprebrano","mapaPoslano":"Poslano","mapaPrejeto":"Prejeto","mapaVsiPogovori":"Vsi pogovori","osebaPreimenujNaslov":"Ime osebe","osebaPreimenujOpis":"Ime velja povsod, kjer se ta oseba pojavi. Prazno = ime iz kanala ({privzeto}).","osebaRazdruzi":"Razdruži","osebaZdruziNaslov":"Združi z drugo osebo","osebaZdruziOpis":"Vsi pogovori izbrane osebe se preselijo k »{ime}«. Razdružiš lahko kadar koli (pano › naslovi).","oznakeNaslov":"Oznake","panoIdentitete":"Naslovi in računi","panoIskanje":"Išči pri tej osebi","panoIskanjePh":"Beseda v sporočilih …","panoNiPriponk":"Še ni datotek.","panoNiZadetkov":"Ni sporočil s tem besedilom.","panoNovaOznaka":"Dodaj oznako …","panoOznake":"Oznake pogovora","panoPreimenuj":"Preimenuj","panoPriponke":"Datoteke v pogovoru","panoZdruzi":"Združi z …","pokaziPano":"Podatki o osebi","privzetoIme":"iz kanala: {ime}","shrani":"Shrani"});
