Object.assign(BESEDILA_OS.es, {"flatpakNaslov":"Web más rápida: cambiar a Flatpak","flatpakPod":"El navegador obtiene el WebKit más reciente de GNOME y se actualiza solo. Unos 420 MB, sin contraseña; Safeer OS se reinicia con los mismos ajustes."});
