Object.assign(BESEDILA_OS.it, {"katKanalSkrit": "Il canale «{ime}» non trasmette, quindi è stato nascosto. Tornerà da solo quando trasmetterà di nuovo.", "katKanaliDeluje": "Canali funzionanti: {n}", "katKanaliPreverjam": "ancora in verifica: {n}", "katKanaliZaklenjeni": "Canali bloccati: {n} – li sblocca un abbonamento presso il fornitore.", "katKanaliIzbira": "Paesi e lingue", "katKanaliIzbiraNamig": "Elenco pubblico: per impostazione predefinita sono attivi i canali del tuo paese e dei paesi anglofoni. Attivane altri qui.", "katKanaliDrzave": "Paesi", "katKanaliJeziki": "Lingue", "katKanalPreverjam": "in verifica", "katKanaliBrezPreverbe": "Canali: {n} – i canali di questo elenco vengono verificati solo durante la riproduzione (protegge un account del fornitore dal blocco)."});
Object.assign(BESEDILA_OS.sl, {"katKanaliJavni": "Javni brezplačni seznam", "katKanaliJavniNamig": "Vklopi samo, če seznam nima računa pri ponudniku: Safeer bo v ozadju preveril vsak kanal, skril tiste, ki ne oddajajo, in seznam delil z vsemi napravami v Linku.", "katVirZavrnjen": "Ponudnik je seznam zavrnil (koda {koda}) – morda je račun potekel ali zaklenjen. Da se račun ne zaklene, ga ne poskusimo znova takoj: samodejno po 10 min, 1 h, 6 h, nato enkrat na dan; tudi ročna osvežitev velja šele po tem premoru."});
Object.assign(BESEDILA_OS.en, {"katKanaliJavni": "Public free list", "katKanaliJavniNamig": "Switch on only if the list has no provider account: Safeer will then check every channel in the background, hide the ones that are not broadcasting and share the list with all devices in Link.", "katVirZavrnjen": "The provider rejected the list (code {koda}) – the account may have expired or been locked. To avoid locking it we do not retry at once: automatically after 10 min, 1 h, 6 h, then once a day; a manual refresh also works only after that pause."});
Object.assign(BESEDILA_OS.de, {"katKanaliJavni": "Öffentliche kostenlose Liste", "katKanaliJavniNamig": "Nur einschalten, wenn die Liste kein Anbieterkonto hat: Safeer prüft dann jeden Sender im Hintergrund, blendet die aus, die nicht senden, und teilt die Liste mit allen Geräten im Link.", "katVirZavrnjen": "Der Anbieter hat die Liste abgelehnt (Code {koda}) – das Konto ist vielleicht abgelaufen oder gesperrt. Damit es nicht gesperrt wird, versuchen wir es nicht sofort erneut: automatisch nach 10 Min., 1 Std., 6 Std., dann einmal täglich; auch die manuelle Aktualisierung gilt erst nach dieser Pause."});
Object.assign(BESEDILA_OS.es, {"katKanaliJavni": "Lista pública gratuita", "katKanaliJavniNamig": "Actívalo solo si la lista no tiene cuenta de proveedor: Safeer comprobará cada canal en segundo plano, ocultará los que no emiten y compartirá la lista con todos los dispositivos de Link.", "katVirZavrnjen": "El proveedor rechazó la lista (código {koda}) – la cuenta puede haber caducado o estar bloqueada. Para no bloquearla no reintentamos enseguida: automáticamente tras 10 min, 1 h, 6 h y luego una vez al día; la actualización manual también vale solo después de esa pausa."});
Object.assign(BESEDILA_OS.fr, {"katKanaliJavni": "Liste publique gratuite", "katKanaliJavniNamig": "Active-le seulement si la liste n’a pas de compte fournisseur : Safeer vérifiera alors chaque chaîne en arrière-plan, masquera celles qui n’émettent pas et partagera la liste avec tous les appareils du Link.", "katVirZavrnjen": "Le fournisseur a refusé la liste (code {koda}) – le compte a peut-être expiré ou été bloqué. Pour ne pas le bloquer, nous ne réessayons pas tout de suite : automatiquement après 10 min, 1 h, 6 h, puis une fois par jour ; l’actualisation manuelle ne vaut aussi qu’après cette pause."});
Object.assign(BESEDILA_OS.it, {"katKanaliJavni": "Elenco pubblico gratuito", "katKanaliJavniNamig": "Attivalo solo se l’elenco non ha un account del fornitore: Safeer verificherà ogni canale in background, nasconderà quelli che non trasmettono e condividerà l’elenco con tutti i dispositivi di Link.", "katVirZavrnjen": "Il fornitore ha rifiutato l’elenco (codice {koda}) – l’account potrebbe essere scaduto o bloccato. Per non bloccarlo non riproviamo subito: automaticamente dopo 10 min, 1 h, 6 h, poi una volta al giorno; anche l’aggiornamento manuale vale solo dopo questa pausa."});
Object.assign(BESEDILA_OS.sl, {"katVirGesloDeljeno": "Geslo tega seznama je bilo deljeno z napravami zunaj ožjega kroga. Priporočamo, da ga zamenjaš pri ponudniku.", "katVirGesloRazumem": "Razumem"});
Object.assign(BESEDILA_OS.sl, {"katVirGesloDeljenoIzbrisan": "Geslo seznama, ki si ga izbrisal, je bilo morda deljeno z napravami zunaj ožjega kroga. Priporočamo, da ga zamenjaš pri ponudniku."});
Object.assign(BESEDILA_OS.sl, {"katVirCaka": "Čaka: vir je prišel z druge naprave in ni znan kot javen (lahko ima račun pri ponudniku), zato se prenese šele, ko ga osvežiš (gumb »Osveži« desno)."});
Object.assign(BESEDILA_OS.sl, {"katVirPrvo": "Prejeto z druge naprave: seznam se prenese, ko odpreš njegovo kategorijo (npr. TV v živo) ali pritisneš »Odpri«, nato le ob odprtju, ko je prebran več kot dan nazaj (največ enkrat na minuto). V ozadju se ne osvežuje."});
