Object.assign(BESEDILA_OS.sl, {"katSkrivniRazkrit": "pred posodobitvijo je bil žeton poslan tudi napravam v Safeer Linku – če želiš, ga pri ponudniku zamenjaj", "katSkrivniHttp": "Dodatek z osebnim žetonom deluje samo prek HTTPS – žeton po HTTP ne gre. Dodaj ga z naslovom https://."});
Object.assign(BESEDILA_OS.en, {"katSkrivniRazkrit": "before the update the token was also sent to devices in Safeer Link – replace it with the provider if you wish", "katSkrivniHttp": "An add-on with a personal token works only over HTTPS – the token is never sent over HTTP. Add it with an https:// address."});
