Object.assign(BESEDILA_OS.es, {"katSkrivniRazkrit": "antes de la actualización el token también se envió a los dispositivos de Safeer Link; si quieres, cámbialo en el proveedor", "katSkrivniHttp": "Un complemento con token personal solo funciona por HTTPS: el token nunca se envía por HTTP. Añádelo con una dirección https://."});
