Object.assign(BESEDILA_OS.it, {"katSkrivniRazkrit": "prima dell’aggiornamento il token è stato inviato anche ai dispositivi in Safeer Link: se vuoi, sostituiscilo presso il fornitore", "katSkrivniHttp": "Un componente aggiuntivo con token personale funziona solo tramite HTTPS: il token non viene mai inviato via HTTP. Aggiungilo con un indirizzo https://."});
Object.assign(BESEDILA_OS.sl, {"unpNaslov": "Usenet ponudnik", "unpOpis": "Lasten ponudnik NNTP: Medijski center predvaja izdaje Usenet neposredno, brez TorBoxa. Geslo ostane šifrirano na tej napravi; strežnik in uporabniško ime dobijo samo naprave v tvojem ožjem krogu.", "unpIme": "Ime (neobvezno)", "unpStreznik": "Strežnik", "unpStreznikPh": "ime strežnika ali naslov IP", "unpVrata": "Vrata", "unpTls": "Šifrirana povezava (TLS)", "unpUporabnik": "Uporabniško ime", "unpUporabnikShranjen": "shranjeno – pusti prazno, če se ne spremeni", "unpGeslo": "Geslo", "unpGesloShranjeno": "shranjeno – vpiši samo za novo geslo", "unpPovezav": "Največ povezav", "unpNamigPovezav": "Vpiši največ toliko, kolikor dovoli tvoj paket. Safeer jih ne odpre več.", "unpOpozoriloBrezTls": "Brez TLS gre geslo po omrežju nešifrirano. Dovoljeno samo do naslova IP v domačem omrežju.", "unpPotrdiBrezTls": "Razumem in vseeno shranim brez TLS", "unpShrani": "Shrani", "unpPreveri": "Preveri", "unpPozabi": "Pozabi ponudnika", "unpPozabiPotrdi": "Klikni znova, da pozabim ponudnika in geslo", "unpPreverjam": "Preverjam prijavo pri ponudniku …", "unpKoda_ni_vpisan": "Usenet se pokaže, ko tukaj vpišeš svojega ponudnika NNTP.", "unpKoda_nepreverjen": "Ponudnik je shranjen. Klikni »Preveri«, če želiš preizkusiti prijavo.", "unpKoda_ni_gesla": "Geslo za ponudnika ni shranjeno. Vpiši ga znova in klikni »Shrani«.", "unpKoda_iz_kroga": "Ponudnika je poslala naprava iz tvojega ožjega kroga. Geslo se ne prenaša – vpiši ga na tej napravi.", "unpKoda_velja": "Prijava pri ponudniku deluje.", "unpKoda_ne_velja": "Ponudnik je zavrnil prijavo. Preveri uporabniško ime in geslo in ju vpiši znova - do takrat Safeer gesla ne pošilja (zaščita pred zaklepom računa).", "unpKoda_zaklenjen": "Prijava je bila zavrnjena, zato Safeer gesla ne pošilja več. Ko poverilnice preveriš pri ponudniku, jih vpiši znova.", "unpKoda_ni_odgovora": "Strežnik ni odgovoril. Preveri strežnik, vrata in omrežje.", "unpKoda_prevec_povezav": "Ponudnik javlja preveč hkratnih povezav. Zapri druge programe ali zmanjšaj število povezav.", "unpKoda_prepogosto": "Preverba je mogoča enkrat na minuto. Poskusi znova čez minuto.", "unpKoda_brez_tls_ni_podprt": "Povezava brez TLS ni podprta. Vklopi TLS (vrata 563).", "unpKoda_n_gostitelj": "Vpiši samo ime strežnika ali naslov IP, brez http:// in vrat.", "unpKoda_n_vrata": "Vrata morajo biti število od 1 do 65535.", "unpKoda_n_uporabnik": "Uporabniško ime ni veljavno.", "unpKoda_n_geslo": "Vpiši geslo (1–400 znakov).", "unpKoda_n_povezav": "Število povezav mora biti od 1 do 100.", "unpKoda_n_ime": "Ime je predolgo ali vsebuje nedovoljene znake.", "unpKoda_n_brez_tls": "Za povezavo brez TLS potrdi opozorilo.", "unpKoda_n_brez_tls_doma": "Brez TLS je dovoljen samo naslov IP v domačem omrežju.", "unpKoda_n_vnos": "Vnos ni veljaven. Preveri polja in poskusi znova.", "unpKoda_geslo_za_spremembo": "Za spremembo strežnika, vrat, TLS ali uporabniškega imena vpiši tudi geslo.", "unpKoda_geslo_ze_zavrnjeno": "Ponudnik je to geslo že zavrnil. Vpiši novo geslo.", "unpKoda_racun_zaklenjen": "Prijava za ta račun je zaklenjena, ker jo je ponudnik zavrnil. Vpiši poverilnice znova.", "unpKoda_v_uporabi": "Ponudnik se uporablja za predvajanje. Preveri ga, ko se predvajanje konča.", "unpKoda_preverba_tece": "Preverba že teče. Počakaj na izid.", "unpKoda_zbirka_ni_dosegljiva": "Sistemska zbirka gesel ni dosegljiva. Odkleni jo in poskusi znova.", "unpKoda_ni_ponudnika": "Ponudnik še ni shranjen.", "unpKoda_glavna_nit": "Preverba se ni začela. Poskusi znova.", "unpKoda_tls_preverba": "Varne povezave ni bilo mogoče pripraviti (preverba potrdila je obvezna).", "unpKoda_napaka": "Ni uspelo. Poskusi znova.", "unpKoda_shranjeno": "Ponudnik je shranjen, geslo je šifrirano v sistemski zbirki.", "unpKoda_shranjeno_zacasno": "Ponudnik je shranjen, geslo pa samo do zaprtja Safeer OS (sistemska zbirka gesel ni dosegljiva).", "unpKoda_posodobljeno": "Ime in število povezav sta posodobljena.", "unpKoda_odstranjeno": "Ponudnik in geslo sta odstranjena s te naprave."});
Object.assign(BESEDILA_OS.en, {"unpNaslov": "Usenet provider", "unpOpis": "Your own NNTP provider: Media Center plays Usenet releases directly, without TorBox. The password stays encrypted on this device; only devices in your inner circle receive the server and username.", "unpIme": "Name (optional)", "unpStreznik": "Server", "unpStreznikPh": "server name or IP address", "unpVrata": "Port", "unpTls": "Encrypted connection (TLS)", "unpUporabnik": "Username", "unpUporabnikShranjen": "saved – leave empty if unchanged", "unpGeslo": "Password", "unpGesloShranjeno": "saved – enter only for a new password", "unpPovezav": "Maximum connections", "unpNamigPovezav": "Enter at most what your plan allows. Safeer never opens more than that.", "unpOpozoriloBrezTls": "Without TLS the password travels unencrypted. Allowed only to an IP address on your home network.", "unpPotrdiBrezTls": "I understand and save without TLS anyway", "unpShrani": "Save", "unpPreveri": "Check", "unpPozabi": "Forget provider", "unpPozabiPotrdi": "Click again to forget the provider and password", "unpPreverjam": "Checking the login with the provider …", "unpKoda_ni_vpisan": "Usenet appears once you enter your own NNTP provider here.", "unpKoda_nepreverjen": "The provider is saved. Click “Check” if you want to test the login.", "unpKoda_ni_gesla": "The provider password is not saved. Enter it again and click “Save”.", "unpKoda_iz_kroga": "A device in your inner circle sent this provider. The password is never transferred – enter it on this device.", "unpKoda_velja": "Login to the provider works.", "unpKoda_ne_velja": "The provider rejected the login. Check your username and password and enter them again - until then Safeer does not send the password (protection against account lockout).", "unpKoda_zaklenjen": "The login was rejected, so Safeer no longer sends the password. Once you have checked your credentials with the provider, enter them again.", "unpKoda_ni_odgovora": "The server did not respond. Check the server, port and network.", "unpKoda_prevec_povezav": "The provider reports too many simultaneous connections. Close other apps or lower the number of connections.", "unpKoda_prepogosto": "You can check once per minute. Try again in a minute.", "unpKoda_brez_tls_ni_podprt": "Connections without TLS are not supported. Turn on TLS (port 563).", "unpKoda_n_gostitelj": "Enter only the server name or IP address, without http:// or a port.", "unpKoda_n_vrata": "The port must be a number from 1 to 65535.", "unpKoda_n_uporabnik": "The username is not valid.", "unpKoda_n_geslo": "Enter the password (1–400 characters).", "unpKoda_n_povezav": "The number of connections must be from 1 to 100.", "unpKoda_n_ime": "The name is too long or contains invalid characters.", "unpKoda_n_brez_tls": "To connect without TLS, confirm the warning.", "unpKoda_n_brez_tls_doma": "Without TLS only an IP address on your home network is allowed.", "unpKoda_n_vnos": "The entry is not valid. Check the fields and try again.", "unpKoda_geslo_za_spremembo": "To change the server, port, TLS or username, enter the password too.", "unpKoda_geslo_ze_zavrnjeno": "The provider already rejected this password. Enter a new password.", "unpKoda_racun_zaklenjen": "Login for this account is locked because the provider rejected it. Enter your credentials again.", "unpKoda_v_uporabi": "The provider is in use for playback. Check it when playback ends.", "unpKoda_preverba_tece": "A check is already running. Wait for the result.", "unpKoda_zbirka_ni_dosegljiva": "The system keyring is not available. Unlock it and try again.", "unpKoda_ni_ponudnika": "No provider is saved yet.", "unpKoda_glavna_nit": "The check did not start. Try again.", "unpKoda_tls_preverba": "A secure connection could not be prepared (certificate verification is required).", "unpKoda_napaka": "That did not work. Try again.", "unpKoda_shranjeno": "The provider is saved; the password is encrypted in the system keyring.", "unpKoda_shranjeno_zacasno": "The provider is saved, but the password only until Safeer OS closes (the system keyring is not available).", "unpKoda_posodobljeno": "The name and number of connections are updated.", "unpKoda_odstranjeno": "The provider and password are removed from this device."});
Object.assign(BESEDILA_OS.de, {"unpNaslov": "Usenet-Anbieter", "unpOpis": "Eigener NNTP-Anbieter: Das Mediencenter spielt Usenet-Releases direkt ab, ohne TorBox. Das Passwort bleibt verschlüsselt auf diesem Gerät; Server und Benutzername erhalten nur Geräte in deinem engsten Kreis.", "unpIme": "Name (optional)", "unpStreznik": "Server", "unpStreznikPh": "Servername oder IP-Adresse", "unpVrata": "Port", "unpTls": "Verschlüsselte Verbindung (TLS)", "unpUporabnik": "Benutzername", "unpUporabnikShranjen": "gespeichert – leer lassen, wenn unverändert", "unpGeslo": "Passwort", "unpGesloShranjeno": "gespeichert – nur für ein neues Passwort eingeben", "unpPovezav": "Maximale Verbindungen", "unpNamigPovezav": "Höchstens so viele, wie dein Tarif erlaubt. Safeer öffnet nie mehr.", "unpOpozoriloBrezTls": "Ohne TLS wird das Passwort unverschlüsselt übertragen. Nur für eine IP-Adresse im Heimnetz erlaubt.", "unpPotrdiBrezTls": "Ich verstehe und speichere trotzdem ohne TLS", "unpShrani": "Speichern", "unpPreveri": "Prüfen", "unpPozabi": "Anbieter entfernen", "unpPozabiPotrdi": "Klicke erneut, um Anbieter und Passwort zu entfernen", "unpPreverjam": "Anmeldung beim Anbieter wird geprüft …", "unpKoda_ni_vpisan": "Usenet erscheint, sobald du hier deinen eigenen NNTP-Anbieter einträgst.", "unpKoda_nepreverjen": "Der Anbieter ist gespeichert. Klicke auf „Prüfen“, um die Anmeldung zu testen.", "unpKoda_ni_gesla": "Das Passwort des Anbieters ist nicht gespeichert. Gib es erneut ein und klicke auf „Speichern“.", "unpKoda_iz_kroga": "Ein Gerät aus deinem engsten Kreis hat diesen Anbieter gesendet. Das Passwort wird nie übertragen – gib es auf diesem Gerät ein.", "unpKoda_velja": "Die Anmeldung beim Anbieter funktioniert.", "unpKoda_ne_velja": "Der Anbieter hat die Anmeldung abgelehnt. Prüfe Benutzername und Passwort und gib sie erneut ein - bis dahin sendet Safeer das Passwort nicht (Schutz vor Kontosperre).", "unpKoda_zaklenjen": "Die Anmeldung wurde abgelehnt, daher sendet Safeer das Passwort nicht mehr. Wenn du die Zugangsdaten beim Anbieter geprüft hast, gib sie erneut ein.", "unpKoda_ni_odgovora": "Der Server hat nicht geantwortet. Prüfe Server, Port und Netzwerk.", "unpKoda_prevec_povezav": "Der Anbieter meldet zu viele gleichzeitige Verbindungen. Schließe andere Programme oder verringere die Anzahl der Verbindungen.", "unpKoda_prepogosto": "Eine Prüfung ist einmal pro Minute möglich. Versuche es in einer Minute erneut.", "unpKoda_brez_tls_ni_podprt": "Verbindungen ohne TLS werden nicht unterstützt. Aktiviere TLS (Port 563).", "unpKoda_n_gostitelj": "Gib nur den Servernamen oder die IP-Adresse ein, ohne http:// und Port.", "unpKoda_n_vrata": "Der Port muss eine Zahl von 1 bis 65535 sein.", "unpKoda_n_uporabnik": "Der Benutzername ist ungültig.", "unpKoda_n_geslo": "Gib das Passwort ein (1–400 Zeichen).", "unpKoda_n_povezav": "Die Anzahl der Verbindungen muss zwischen 1 und 100 liegen.", "unpKoda_n_ime": "Der Name ist zu lang oder enthält ungültige Zeichen.", "unpKoda_n_brez_tls": "Bestätige die Warnung, um ohne TLS zu verbinden.", "unpKoda_n_brez_tls_doma": "Ohne TLS ist nur eine IP-Adresse im Heimnetz erlaubt.", "unpKoda_n_vnos": "Die Eingabe ist ungültig. Prüfe die Felder und versuche es erneut.", "unpKoda_geslo_za_spremembo": "Um Server, Port, TLS oder Benutzername zu ändern, gib auch das Passwort ein.", "unpKoda_geslo_ze_zavrnjeno": "Der Anbieter hat dieses Passwort bereits abgelehnt. Gib ein neues Passwort ein.", "unpKoda_racun_zaklenjen": "Die Anmeldung für dieses Konto ist gesperrt, weil der Anbieter sie abgelehnt hat. Gib die Zugangsdaten erneut ein.", "unpKoda_v_uporabi": "Der Anbieter wird gerade für die Wiedergabe genutzt. Prüfe ihn nach dem Ende der Wiedergabe.", "unpKoda_preverba_tece": "Eine Prüfung läuft bereits. Warte auf das Ergebnis.", "unpKoda_zbirka_ni_dosegljiva": "Der System-Schlüsselbund ist nicht erreichbar. Entsperre ihn und versuche es erneut.", "unpKoda_ni_ponudnika": "Es ist noch kein Anbieter gespeichert.", "unpKoda_glavna_nit": "Die Prüfung wurde nicht gestartet. Versuche es erneut.", "unpKoda_tls_preverba": "Eine sichere Verbindung konnte nicht vorbereitet werden (Zertifikatsprüfung ist Pflicht).", "unpKoda_napaka": "Das hat nicht geklappt. Versuche es erneut.", "unpKoda_shranjeno": "Der Anbieter ist gespeichert; das Passwort ist im System-Schlüsselbund verschlüsselt.", "unpKoda_shranjeno_zacasno": "Der Anbieter ist gespeichert, das Passwort aber nur bis zum Schließen von Safeer OS (System-Schlüsselbund nicht erreichbar).", "unpKoda_posodobljeno": "Name und Anzahl der Verbindungen sind aktualisiert.", "unpKoda_odstranjeno": "Anbieter und Passwort sind von diesem Gerät entfernt."});
Object.assign(BESEDILA_OS.es, {"unpNaslov": "Proveedor de Usenet", "unpOpis": "Tu propio proveedor NNTP: el Centro multimedia reproduce las publicaciones de Usenet directamente, sin TorBox. La contraseña se queda cifrada en este dispositivo; solo los dispositivos de tu círculo cercano reciben el servidor y el usuario.", "unpIme": "Nombre (opcional)", "unpStreznik": "Servidor", "unpStreznikPh": "nombre del servidor o dirección IP", "unpVrata": "Puerto", "unpTls": "Conexión cifrada (TLS)", "unpUporabnik": "Nombre de usuario", "unpUporabnikShranjen": "guardado: déjalo vacío si no cambia", "unpGeslo": "Contraseña", "unpGesloShranjeno": "guardada: escríbela solo si es nueva", "unpPovezav": "Conexiones máximas", "unpNamigPovezav": "Introduce como máximo las que permite tu plan. Safeer nunca abre más.", "unpOpozoriloBrezTls": "Sin TLS la contraseña viaja sin cifrar. Solo se permite a una dirección IP de tu red doméstica.", "unpPotrdiBrezTls": "Lo entiendo y guardo sin TLS de todos modos", "unpShrani": "Guardar", "unpPreveri": "Comprobar", "unpPozabi": "Olvidar proveedor", "unpPozabiPotrdi": "Haz clic de nuevo para olvidar el proveedor y la contraseña", "unpPreverjam": "Comprobando el inicio de sesión en el proveedor …", "unpKoda_ni_vpisan": "Usenet aparece cuando introduces aquí tu propio proveedor NNTP.", "unpKoda_nepreverjen": "El proveedor está guardado. Haz clic en «Comprobar» si quieres probar el inicio de sesión.", "unpKoda_ni_gesla": "La contraseña del proveedor no está guardada. Vuelve a introducirla y haz clic en «Guardar».", "unpKoda_iz_kroga": "Un dispositivo de tu círculo cercano envió este proveedor. La contraseña nunca se transfiere: introdúcela en este dispositivo.", "unpKoda_velja": "El inicio de sesión en el proveedor funciona.", "unpKoda_ne_velja": "El proveedor rechazó el inicio de sesión. Revisa el usuario y la contraseña y vuelve a introducirlos; hasta entonces Safeer no envía la contraseña (protección contra el bloqueo de la cuenta).", "unpKoda_zaklenjen": "El inicio de sesión fue rechazado, así que Safeer ya no envía la contraseña. Cuando hayas comprobado tus credenciales con el proveedor, vuelve a introducirlas.", "unpKoda_ni_odgovora": "El servidor no respondió. Revisa el servidor, el puerto y la red.", "unpKoda_prevec_povezav": "El proveedor indica demasiadas conexiones simultáneas. Cierra otras aplicaciones o reduce el número de conexiones.", "unpKoda_prepogosto": "Solo se puede comprobar una vez por minuto. Inténtalo de nuevo en un minuto.", "unpKoda_brez_tls_ni_podprt": "No se admiten conexiones sin TLS. Activa TLS (puerto 563).", "unpKoda_n_gostitelj": "Introduce solo el nombre del servidor o la dirección IP, sin http:// ni puerto.", "unpKoda_n_vrata": "El puerto debe ser un número del 1 al 65535.", "unpKoda_n_uporabnik": "El nombre de usuario no es válido.", "unpKoda_n_geslo": "Introduce la contraseña (1–400 caracteres).", "unpKoda_n_povezav": "El número de conexiones debe estar entre 1 y 100.", "unpKoda_n_ime": "El nombre es demasiado largo o contiene caracteres no válidos.", "unpKoda_n_brez_tls": "Para conectar sin TLS, confirma la advertencia.", "unpKoda_n_brez_tls_doma": "Sin TLS solo se permite una dirección IP de tu red doméstica.", "unpKoda_n_vnos": "La entrada no es válida. Revisa los campos e inténtalo de nuevo.", "unpKoda_geslo_za_spremembo": "Para cambiar el servidor, el puerto, TLS o el usuario, introduce también la contraseña.", "unpKoda_geslo_ze_zavrnjeno": "El proveedor ya rechazó esta contraseña. Introduce una nueva.", "unpKoda_racun_zaklenjen": "El inicio de sesión de esta cuenta está bloqueado porque el proveedor lo rechazó. Vuelve a introducir tus credenciales.", "unpKoda_v_uporabi": "El proveedor se está usando para reproducir. Compruébalo cuando termine la reproducción.", "unpKoda_preverba_tece": "Ya hay una comprobación en curso. Espera el resultado.", "unpKoda_zbirka_ni_dosegljiva": "El llavero del sistema no está disponible. Desbloquéalo e inténtalo de nuevo.", "unpKoda_ni_ponudnika": "Todavía no hay ningún proveedor guardado.", "unpKoda_glavna_nit": "La comprobación no se inició. Inténtalo de nuevo.", "unpKoda_tls_preverba": "No se pudo preparar una conexión segura (la verificación del certificado es obligatoria).", "unpKoda_napaka": "No ha funcionado. Inténtalo de nuevo.", "unpKoda_shranjeno": "El proveedor está guardado; la contraseña está cifrada en el llavero del sistema.", "unpKoda_shranjeno_zacasno": "El proveedor está guardado, pero la contraseña solo hasta cerrar Safeer OS (el llavero del sistema no está disponible).", "unpKoda_posodobljeno": "El nombre y el número de conexiones están actualizados.", "unpKoda_odstranjeno": "El proveedor y la contraseña se han eliminado de este dispositivo."});
